import{_ as o,o as e,c as l,a2 as i}from"./chunks/framework.BUwdTBzS.js";const g=JSON.parse('{"title":"CSS_官方规范","description":"css 代码规范","frontmatter":{"title":"CSS_官方规范","description":"css 代码规范"},"headers":[],"relativePath":"rules/CSS_官方规范.md","filePath":"rules/CSS_官方规范.md","lastUpdated":null}'),r={name:"rules/CSS_官方规范.md"};function t(s,a,n,d,c,h){return e(),l("div",null,[...a[0]||(a[0]=[i('<blockquote><p>📄 本页由源文件 <code>rules/CSS_官方规范.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="css-官方规范" tabindex="-1">CSS_官方规范 <a class="header-anchor" href="#css-官方规范" aria-label="Permalink to &quot;CSS_官方规范&quot;">​</a></h1><p>你是一个专业的CSS开发助手，所有代码必须严格遵循以下编码规范。</p><h2 id="基础规范" tabindex="-1">基础规范 <a class="header-anchor" href="#基础规范" aria-label="Permalink to &quot;基础规范&quot;">​</a></h2><p><strong>注意：如果没有明确说明，需要遵循 <a href="https://github.com/airbnb/css" target="_blank" rel="noreferrer">Airbnb CSS编码规范</a>。</strong></p><h2 id="规范等级说明" tabindex="-1">规范等级说明 <a class="header-anchor" href="#规范等级说明" aria-label="Permalink to &quot;规范等级说明&quot;">​</a></h2><ul><li><strong>【必须】</strong> 级别要求必须严格按照规范编码，否则在代码扫描和自动化构建中报错</li><li><strong>【推荐】</strong> 级别希望尽量按照规范编写，特殊情况可以不采用</li><li><strong>【可选】</strong> 级别不强制要求，但建议参考规范编写</li></ul><h2 id="css格式规范" tabindex="-1">CSS格式规范 <a class="header-anchor" href="#css格式规范" aria-label="Permalink to &quot;CSS格式规范&quot;">​</a></h2><h3 id="缩进和空格" tabindex="-1">缩进和空格 <a class="header-anchor" href="#缩进和空格" aria-label="Permalink to &quot;缩进和空格&quot;">​</a></h3><ul><li><strong>【必须】</strong> 使用2个空格作为缩进，不使用tab</li><li><strong>【必须】</strong> 在规则声明的左大括号 <code>{</code> 前加上一个空格</li><li><strong>【必须】</strong> 在属性的冒号 <code>:</code> 后面加上一个空格，前面不加空格</li><li><strong>【必须】</strong> 规则声明的右大括号 <code>}</code> 独占一行</li></ul><h3 id="选择器规范" tabindex="-1">选择器规范 <a class="header-anchor" href="#选择器规范" aria-label="Permalink to &quot;选择器规范&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 类名使用破折号代替驼峰法，推荐使用BEM方式命名 <ul><li>块（block）：<code>.listing-card</code></li><li>元素（element）：<code>.listing-card__title</code></li><li>修饰符（modifier）：<code>.listing-card--featured</code></li></ul></li><li><strong>【必须】</strong> 不要使用ID选择器，使用class选择器代替</li><li><strong>【必须】</strong> 多个选择器时，每个选择器独占一行</li></ul><h3 id="属性规范" tabindex="-1">属性规范 <a class="header-anchor" href="#属性规范" aria-label="Permalink to &quot;属性规范&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 颜色值用小写，能用3位表示的推荐用3位：<code>#fff</code> 而不是 <code>#ffffff</code></li><li><strong>【必须】</strong> 不要使用 <code>!important</code></li><li><strong>【必须】</strong> 定义无边框样式时，使用 <code>0</code> 代替 <code>none</code></li><li><strong>【必须】</strong> 禁止小于1的小数前加0：使用 <code>.5</code> 而不是 <code>0.5</code></li><li><strong>【必须】</strong> 字符串使用单引号：<code>content: &#39;x&#39;</code> 而不是 <code>content: &quot;x&quot;</code></li><li><strong>【必须】</strong> 单行属性声明块中只允许声明一个属性</li></ul><h3 id="状态和伪元素" tabindex="-1">状态和伪元素 <a class="header-anchor" href="#状态和伪元素" aria-label="Permalink to &quot;状态和伪元素&quot;">​</a></h3><ul><li><strong>【推荐】</strong> before、after、active、focus等状态只使用一个 <code>:</code><ul><li>使用 <code>&amp;:before</code> 而不是 <code>&amp;::before</code></li><li>使用 <code>&amp;:active</code> 而不是 <code>&amp;::active</code></li></ul></li></ul><h3 id="浏览器前缀" tabindex="-1">浏览器前缀 <a class="header-anchor" href="#浏览器前缀" aria-label="Permalink to &quot;浏览器前缀&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 样式中不要添加浏览器前缀，由编译工具自动添加</li></ul><h3 id="嵌套深度" tabindex="-1">嵌套深度 <a class="header-anchor" href="#嵌套深度" aria-label="Permalink to &quot;嵌套深度&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 最大嵌套深度为10层</li></ul><h2 id="注释规范" tabindex="-1">注释规范 <a class="header-anchor" href="#注释规范" aria-label="Permalink to &quot;注释规范&quot;">​</a></h2><h3 id="注释格式" tabindex="-1">注释格式 <a class="header-anchor" href="#注释格式" aria-label="Permalink to &quot;注释格式&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 建议使用行注释 (在 Sass 中是 <code>//</code>) 代替块注释</li><li><strong>【推荐】</strong> 非首行注释，需要在注释前空行</li></ul><h3 id="注释内容" tabindex="-1">注释内容 <a class="header-anchor" href="#注释内容" aria-label="Permalink to &quot;注释内容&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 给需要注释的代码写上详细说明： <ul><li>为什么用到了 z-index</li><li>兼容性处理或针对特定浏览器的hack</li></ul></li><li><strong>【推荐】</strong> 在HTML上说明加上某个类的作用</li></ul><h2 id="javascript钩子" tabindex="-1">JavaScript钩子 <a class="header-anchor" href="#javascript钩子" aria-label="Permalink to &quot;JavaScript钩子&quot;">​</a></h2><ul><li><strong>【推荐】</strong> 避免在CSS和JavaScript中绑定相同的类</li><li><strong>【推荐】</strong> 为JavaScript专用的类名添加 <code>js-</code> 前缀</li></ul><h2 id="sass规范" tabindex="-1">Sass规范 <a class="header-anchor" href="#sass规范" aria-label="Permalink to &quot;Sass规范&quot;">​</a></h2><h3 id="语法要求" tabindex="-1">语法要求 <a class="header-anchor" href="#语法要求" aria-label="Permalink to &quot;语法要求&quot;">​</a></h3><ul><li><strong>【必须】</strong> 使用 <code>.scss</code> 语法，不使用 <code>.sass</code> 原本语法</li><li><strong>【推荐】</strong> 不要嵌套ID选择器</li></ul><h3 id="属性声明排序" tabindex="-1">属性声明排序 <a class="header-anchor" href="#属性声明排序" aria-label="Permalink to &quot;属性声明排序&quot;">​</a></h3><ul><li><strong>【必须】</strong> 按以下顺序排列： <ol><li>属性声明（除去 @include 和嵌套选择器）</li><li>@include 声明</li><li>嵌套选择器</li></ol></li></ul><h3 id="变量命名" tabindex="-1">变量命名 <a class="header-anchor" href="#变量命名" aria-label="Permalink to &quot;变量命名&quot;">​</a></h3><ul><li><strong>【必须】</strong> 变量名使用破折号：<code>$my-variable</code></li><li><strong>【推荐】</strong> 仅用于当前文件的变量可添加下划线前缀：<code>$_my-variable</code></li></ul><h3 id="import语句" tabindex="-1">@import语句 <a class="header-anchor" href="#import语句" aria-label="Permalink to &quot;@import语句&quot;">​</a></h3><ul><li><strong>【推荐】</strong> @import语句引用文件必须写在引号内，<code>.scss</code>后缀不得省略，使用双引号</li></ul><h3 id="mixins规范" tabindex="-1">Mixins规范 <a class="header-anchor" href="#mixins规范" aria-label="Permalink to &quot;Mixins规范&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 使用mixin遵循DRY原则</li><li><strong>【推荐】</strong> Mixin和括号之间不得包含空格</li><li><strong>【推荐】</strong> 参数分隔符后保留一个空格</li></ul><h3 id="扩展指令" tabindex="-1">扩展指令 <a class="header-anchor" href="#扩展指令" aria-label="Permalink to &quot;扩展指令&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 避免使用 <code>@extend</code> 指令，因为它并不直观，而且具有潜在风险，特别是用在嵌套选择器的时候，建议用mixin代替</li></ul><h3 id="sass变量和占位符" tabindex="-1">Sass变量和占位符 <a class="header-anchor" href="#sass变量和占位符" aria-label="Permalink to &quot;Sass变量和占位符&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 指定sass变量指定模式</li><li><strong>【推荐】</strong> 禁止在@extend后缺失占位符，使用 <code>%placeholder</code> 而不是 <code>.some-class</code></li></ul><h2 id="less规范" tabindex="-1">Less规范 <a class="header-anchor" href="#less规范" aria-label="Permalink to &quot;Less规范&quot;">​</a></h2><h3 id="代码组织" tabindex="-1">代码组织 <a class="header-anchor" href="#代码组织" aria-label="Permalink to &quot;代码组织&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 按以下顺序组织代码： <ol><li>import</li><li>变量声明</li><li>样式声明</li></ol></li></ul><h3 id="import语句-1" tabindex="-1">@import语句 <a class="header-anchor" href="#import语句-1" aria-label="Permalink to &quot;@import语句&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 引用文件必须写在引号内，<code>.less</code>后缀不得省略，使用双引号</li></ul><h3 id="变量命名-1" tabindex="-1">变量命名 <a class="header-anchor" href="#变量命名-1" aria-label="Permalink to &quot;变量命名&quot;">​</a></h3><ul><li><strong>【必须】</strong> 变量名使用破折号：<code>@my-variable</code></li><li><strong>【推荐】</strong> 仅用于当前文件的变量可添加下划线前缀：<code>@_my-variable</code></li></ul><h3 id="运算规范" tabindex="-1">运算规范 <a class="header-anchor" href="#运算规范" aria-label="Permalink to &quot;运算规范&quot;">​</a></h3><ul><li><strong>【推荐】</strong> <code>+</code>, <code>-</code>, <code>*</code>, <code>/</code> 四个运算符两侧保留一个空格</li><li><strong>【推荐】</strong> <code>+</code>, <code>-</code> 两侧操作数使用相同单位</li></ul><h3 id="mixins规范-1" tabindex="-1">Mixins规范 <a class="header-anchor" href="#mixins规范-1" aria-label="Permalink to &quot;Mixins规范&quot;">​</a></h3><ul><li><strong>【推荐】</strong> Mixin和括号之间不得包含空格，参数分隔符后保留空格</li><li><strong>【推荐】</strong> 定义mixin时，如果不是className，加上括号</li><li><strong>【推荐】</strong> 调用不输出内容的mixin时，添加括号以区分className</li></ul><h3 id="继承规范" tabindex="-1">继承规范 <a class="header-anchor" href="#继承规范" aria-label="Permalink to &quot;继承规范&quot;">​</a></h3><ul><li><strong>【推荐】</strong> 使用继承时，<code>:extend</code> 语句写在声明块开头</li></ul><h2 id="工具配置建议" tabindex="-1">工具配置建议 <a class="header-anchor" href="#工具配置建议" aria-label="Permalink to &quot;工具配置建议&quot;">​</a></h2><ul><li>推荐使用 Prettier 美化器自动格式化代码</li><li>推荐使用 stylelint 进行代码检查</li><li>推荐使用编译工具自动添加浏览器前缀</li></ul>',57)])])}const b=o(r,[["render",t]]);export{g as __pageData,b as default};
